async function fillUtilitiesCheckboxes(session, els, report) {
  if (!report.utilities) {
    addLog(session, "\u2139\uFE0F \u0644\u0627 \u064A\u0648\u062C\u062F \u0645\u0631\u0627\u0641\u0642 \u0641\u064A \u0627\u0644\u062A\u0642\u0631\u064A\u0631 \u2014 \u062A\u062C\u0627\u0648\u0632");
    return;
  }
  const { page } = session;
  const utilitiesText = String(report.utilities);
  addLog(session, `\u{1F527} \u0627\u0644\u0645\u0631\u0627\u0641\u0642 \u2014 \u0646\u0635 \u0627\u0644\u062A\u0642\u0631\u064A\u0631: "${utilitiesText.slice(0, 150)}"`);
  const analysis = await page.evaluate((utxt) => {
    function normAr(s) {
      return (s || "").replace(/[\u064B-\u065F\u0670\u0640]/g, "").replace(/[\u0623\u0625\u0622\u0671]/g, "\u0627").replace(/[\u064A\u0649\u06CC]/g, "\u064A").replace(/\u0629/g, "\u0647").replace(/\s+/g, " ").trim().toLowerCase();
    }
    function fuzzy(a, b) {
      const na = normAr(a), nb = normAr(b);
      if (na === nb) return true;
      const sa = na.replace(/^\u0627\u0644/, ""), sb = nb.replace(/^\u0627\u0644/, "");
      if (sa === sb) return true;
      if (na.length > 2 && nb.length > 2 && (na.includes(nb) || nb.includes(na))) return true;
      if (sa.length > 2 && sb.length > 2 && (sa.includes(sb) || sb.includes(sa))) return true;
      return false;
    }
    const items = utxt.split(/[,،\/\n]+/).map((s) => s.trim()).filter(Boolean);
    const results = [];
    const checkboxes = Array.from(document.querySelectorAll("mat-checkbox"));
    for (const cb of checkboxes) {
      const text = (cb.textContent ?? "").replace(/\s+/g, " ").trim();
      if (!text) continue;
      const inp = cb.querySelector("input[type='checkbox']");
      const isChecked = inp ? inp.checked : false;
      const shouldCheck = items.some((item) => fuzzy(item, text));
      results.push({ text, shouldCheck, isChecked });
    }
    return results;
  }, utilitiesText).catch(() => []);
  addLog(
    session,
    `\u{1F50D} mat-checkboxes \u0641\u064A \u0627\u0644\u0635\u0641\u062D\u0629 (${analysis.length}): ${analysis.map((c) => c.text).join(" | ")}`
  );
  const toCheck = analysis.filter((c) => c.shouldCheck && !c.isChecked);
  const alreadyOn = analysis.filter((c) => c.shouldCheck && c.isChecked);
  if (alreadyOn.length > 0)
    addLog(session, `\u2705 \u0645\u064F\u0641\u0639\u064E\u0651\u0644\u0629 \u0645\u0633\u0628\u0642\u0627\u064B: ${alreadyOn.map((c) => c.text).join(", ")}`);
  if (toCheck.length === 0) {
    addLog(session, "\u2139\uFE0F \u0644\u0627 \u062A\u0648\u062C\u062F \u0645\u0631\u0627\u0641\u0642 \u062A\u062D\u062A\u0627\u062C \u062A\u0641\u0639\u064A\u0644\u0627\u064B");
    return;
  }
  addLog(session, `\u{1F518} \u0644\u0644\u062A\u0641\u0639\u064A\u0644 (${toCheck.length}): ${toCheck.map((c) => c.text).join(", ")}`);
  const waitStable = async () => {
    await page.waitForFunction(() => {
      const w = window;
      if (typeof w.getAllAngularTestabilities === "function")
        return w.getAllAngularTestabilities().every((t) => t.isStable());
      return true;
    }, { timeout: 3e3 }).catch(() => {
    });
    await page.waitForTimeout(120);
  };
  for (const util of toCheck) {
    const rx = new RegExp(
      util.text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").slice(0, 30),
      "i"
    );
    await waitStable();
    const matCb = page.locator("mat-checkbox").filter({ hasText: rx }).first();
    if (await matCb.count().catch(() => 0) === 0) {
      addLog(session, `\u26A0\uFE0F "${util.text}": \u0644\u0645 \u064A\u064F\u0639\u062B\u0631 \u0639\u0644\u064A\u0647 \u2014 \u062A\u062C\u0627\u0648\u0632`);
      continue;
    }
    let success = false;
    for (let attempt = 1; attempt <= 3 && !success; attempt++) {
      try {
        const lbl = matCb.locator("label").first();
        if (await lbl.count().catch(() => 0) > 0) {
          await lbl.scrollIntoViewIfNeeded().catch(() => {
          });
          await lbl.click({ timeout: 2e3 });
        } else {
          await matCb.scrollIntoViewIfNeeded().catch(() => {
          });
          await matCb.click({ timeout: 2e3 });
        }
        await waitStable();
        success = await matCb.locator("input[type='checkbox']").isChecked().catch(() => false);
      } catch {
        try {
          await page.evaluate((txt) => {
            function normAr(s) {
              return (s || "").replace(/[\u064B-\u065F\u0670\u0640]/g, "").replace(/[\u0623\u0625\u0622\u0671]/g, "\u0627").replace(/[\u064A\u0649]/g, "\u064A").replace(/\u0629/g, "\u0647").replace(/\s+/g, " ").trim().toLowerCase();
            }
            const nt = normAr(txt);
            const cbs = Array.from(document.querySelectorAll("mat-checkbox"));
            const cb = cbs.find((c) => normAr((c.textContent || "").replace(/\s+/g, " ").trim()).includes(nt.slice(0, 8)));
            const inp = cb?.querySelector("input[type='checkbox']");
            if (inp && !inp.checked) {
              inp.click();
              inp.dispatchEvent(new Event("change", { bubbles: true }));
            }
          }, util.text);
          await waitStable();
          success = await matCb.locator("input[type='checkbox']").isChecked().catch(() => false);
        } catch {
        }
      }
      if (!success && attempt < 3) await page.waitForTimeout(300);
    }
    addLog(session, success ? `\u2705 "${util.text}": \u062A\u0645 \u062A\u0641\u0639\u064A\u0644\u0647` : `\u274C "${util.text}": \u0641\u0634\u0644 \u0627\u0644\u062A\u0641\u0639\u064A\u0644`);
  }
  await page.waitForTimeout(200);
}
function findEl(arr, rx) {
  return arr.find((e) => {
    const combined = [
      e.formControlName,
      e.name,
      e.id,
      e.placeholder,
      e.labelText,
      e.ariaLabel
    ].join("|").toLowerCase();
    return rx.test(combined);
  });
}
